// Overfold — a turn-based spatial-transform puzzle.
//
// You fold a paper grid onto itself; the smaller flap reflects across the
// crease and superimposes onto the cells beneath. Matching pips SEAL, pips over
// empty TRANSFER, mismatched pips JAM into a permanent fault.
//
// Pure, deterministic engine. NO Math.random / Date / DOM anywhere in this file.
// The ONLY randomness source is the injected `Rng`, and it appears ONLY inside
// generateBoard / newGame / nextLevel. Every board is generated by inverse folds
// so it is provably solvable with a known par fold count.

export const MAX_DIM = 6 // paper never exceeds 6×6
export const EMPTY = -1 // no pip
export const JAM = -2 // permanent fault (blocks the cell forever)
export const BASE_SEAL = 10 // score unit per seal
export const PAR_BONUS = 200 // awarded on a win at or under par
export const FOLD_SLACK = 3 // hard fold budget = par + FOLD_SLACK
export const UNFOLD_POOL = 3 // undos available per board

// A Cell is a single number:
//   -2 = JAM, -1 = EMPTY, 0..N = a color id (each color id appears as a matched PAIR)
export type Cell = number

export type Rng = () => number // returns [0,1)
export type Axis = 'v' | 'h' // 'v' = vertical crease (splits columns); 'h' = horizontal (splits rows)
export type Prefer = 'low' | 'high' // tie-breaker only: which side folds when both sides are equal width
export type Mode = 'random' | 'daily'

export interface Board {
  w: number // 1..6
  h: number // 1..6
  cells: Cell[] // length w*h, row-major
}

export interface FoldMove {
  axis: Axis
  index: number
  prefer: Prefer
}

export type OverlapKind =
  | 'seal' // same color onto same color -> both removed
  | 'transfer' // color onto EMPTY -> pip moves in
  | 'jam' // two different colors collide -> new JAM; OR a JAM lands on a non-jam cell
  | 'blocked' // a color pip folds onto an existing JAM -> pip is destroyed, cell stays JAM
  | 'none' // EMPTY flap cell onto anything -> no change

/** One flap cell mapped onto its landing cell, in CURRENT-board coordinates (for the ghost preview). */
export interface OverlapPair {
  flapIndex: number // flat index (current board) of the folding cell
  baseIndex: number // flat index (current board) of the cell it lands on
  kind: OverlapKind
  color: Cell // for 'seal'/'transfer' the pip color; else the resulting cell value
}

export interface FoldPreview {
  legal: boolean
  axis: Axis
  index: number
  prefer: Prefer
  flapSide: 'low' | 'high' // which side folds (low = left/top, high = right/bottom)
  overlaps: OverlapPair[] // one entry per flap cell in the overlap region
  seals: number
  jamsFormed: number
  scoreDelta: number // scoreForSeals(seals)
  next: Board // the resolved, shrunken board this fold would produce
}

export interface Snapshot {
  board: Board
  score: number
  foldsUsed: number
}

export interface GameState {
  board: Board
  par: number // generator-guaranteed minimum fold count
  foldsUsed: number
  foldBudget: number // par + FOLD_SLACK
  unfoldsLeft: number
  score: number
  seed: number
  mode: Mode
  level: number // 1-based; drives par & density
  solution: FoldMove[] // recorded par solution in FORWARD order (used for the optional single-hint)
  history: Snapshot[] // bounded undo stack (<= foldBudget deep)
  won: boolean
  lost: boolean
}

// ---------------------------------------------------------------------------
// 1.3 Deterministic PRNG
// ---------------------------------------------------------------------------

/** Pure seeded PRNG. Uses Math.imul + bit ops only — NO Math.random. */
export function mulberry32(seed: number): Rng {
  let a = seed >>> 0
  return () => {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

// ---------------------------------------------------------------------------
// 1.4 Geometry & resolution (rng-free, total functions)
// ---------------------------------------------------------------------------

/** Count of cells holding a color pip (value >= 0). JAM/EMPTY excluded. */
export function pipCount(board: Board): number {
  let n = 0
  for (const c of board.cells) if (c >= 0) n++
  return n
}

/** True when the paper holds at least one JAM. Jams are permanent (no fold removes one). */
export function hasJam(board: Board): boolean {
  return board.cells.some((c) => c === JAM)
}

/**
 * A board is cleared only when every pair has SEALED: no pips left AND no jam.
 * (A jam also deletes pips, so "zero pips" alone let random folding win ~100%.)
 */
export function isWon(board: Board): boolean {
  return pipCount(board) === 0 && !hasJam(board)
}

export function inBounds(board: Board, axis: Axis, index: number): boolean {
  if (!Number.isInteger(index)) return false
  if (axis === 'v') return index >= 1 && index <= board.w - 1
  return index >= 1 && index <= board.h - 1
}

/** All legal creases, ascending: vertical index in [1, w-1], then horizontal index in [1, h-1]. */
export function legalCreases(board: Board): { axis: Axis; index: number }[] {
  const out: { axis: Axis; index: number }[] = []
  for (let i = 1; i <= board.w - 1; i++) out.push({ axis: 'v', index: i })
  for (let i = 1; i <= board.h - 1; i++) out.push({ axis: 'h', index: i })
  return out
}

/**
 * A crease at `index k` sits between line k-1 and k. Low side = [0, k-1] (width k);
 * high side = [k, dim-1] (width dim-k). The strictly-smaller side always folds;
 * on a tie `prefer` decides.
 */
export function creaseSides(
  board: Board,
  axis: Axis,
  index: number,
  prefer: Prefer,
): { flapSide: 'low' | 'high'; lowWidth: number; highWidth: number } {
  const dim = axis === 'v' ? board.w : board.h
  const lowWidth = index
  const highWidth = dim - index
  let flapSide: 'low' | 'high'
  if (lowWidth < highWidth) flapSide = 'low'
  else if (highWidth < lowWidth) flapSide = 'high'
  else flapSide = prefer
  return { flapSide, lowWidth, highWidth }
}

/** The complete §1.4 overlap truth table. `f` = incoming flap value, `g` = base value. */
export function resolveOverlap(f: Cell, g: Cell): { val: Cell; kind: OverlapKind } {
  if (f === EMPTY) return { val: g, kind: 'none' }
  if (f === JAM) {
    if (g === JAM) return { val: JAM, kind: 'none' }
    return { val: JAM, kind: 'jam' }
  }
  // f is a color pip (>= 0)
  if (g === EMPTY) return { val: f, kind: 'transfer' }
  if (g === JAM) return { val: JAM, kind: 'blocked' }
  if (g === f) return { val: EMPTY, kind: 'seal' }
  return { val: JAM, kind: 'jam' } // g is a different color
}

/** Multi-seals in ONE fold escalate triangularly: 1=10, 2=30, 3=60, 4=100. */
export function scoreForSeals(seals: number): number {
  return (BASE_SEAL * seals * (seals + 1)) / 2
}

// ---------------------------------------------------------------------------
// 1.5 Preview & fold
// ---------------------------------------------------------------------------

function illegalPreview(board: Board, axis: Axis, index: number, prefer: Prefer): FoldPreview {
  return {
    legal: false,
    axis,
    index,
    prefer,
    flapSide: 'low',
    overlaps: [],
    seals: 0,
    jamsFormed: 0,
    scoreDelta: 0,
    next: board,
  }
}

/**
 * Pure, rng-free. Computes the full outcome of folding `axis/index/prefer`
 * WITHOUT any game-state bookkeeping. Drives both the ghost preview and applyFold.
 */
export function previewFold(board: Board, axis: Axis, index: number, prefer: Prefer): FoldPreview {
  if (!inBounds(board, axis, index)) return illegalPreview(board, axis, index, prefer)

  const { flapSide } = creaseSides(board, axis, index, prefer)
  const { w, h } = board
  const overlaps: OverlapPair[] = []
  let seals = 0
  let jamsFormed = 0

  const k = index

  if (axis === 'v') {
    // Vertical crease: fold columns, rows untouched.
    const newW = flapSide === 'low' ? w - k : k
    const cells = new Array<Cell>(newW * h)
    for (let r = 0; r < h; r++) {
      for (let ns = 0; ns < newW; ns++) {
        const oldBaseCol = flapSide === 'low' ? ns + k : ns
        const g = board.cells[r * w + oldBaseCol]
        // A flap cell overlaps this survivor iff it reflects onto it.
        let flapCol = -1
        if (flapSide === 'low') {
          if (oldBaseCol >= k && oldBaseCol <= 2 * k - 1) flapCol = 2 * k - 1 - oldBaseCol
        } else {
          if (oldBaseCol >= 2 * k - w && oldBaseCol <= k - 1) flapCol = 2 * k - 1 - oldBaseCol
        }
        if (flapCol >= 0 && flapCol <= w - 1) {
          const f = board.cells[r * w + flapCol]
          const { val, kind } = resolveOverlap(f, g)
          cells[r * newW + ns] = val
          if (kind === 'seal') seals++
          else if (kind === 'jam') jamsFormed++
          overlaps.push({
            flapIndex: r * w + flapCol,
            baseIndex: r * w + oldBaseCol,
            kind,
            color: kind === 'seal' || kind === 'transfer' ? f : val,
          })
        } else {
          cells[r * newW + ns] = g
        }
      }
    }
    return {
      legal: true,
      axis,
      index,
      prefer,
      flapSide,
      overlaps,
      seals,
      jamsFormed,
      scoreDelta: scoreForSeals(seals),
      next: { w: newW, h, cells },
    }
  }

  // Horizontal crease: fold rows, columns untouched.
  const newH = flapSide === 'low' ? h - k : k
  const cells = new Array<Cell>(w * newH)
  for (let ns = 0; ns < newH; ns++) {
    const oldBaseRow = flapSide === 'low' ? ns + k : ns
    let flapRow = -1
    if (flapSide === 'low') {
      if (oldBaseRow >= k && oldBaseRow <= 2 * k - 1) flapRow = 2 * k - 1 - oldBaseRow
    } else {
      if (oldBaseRow >= 2 * k - h && oldBaseRow <= k - 1) flapRow = 2 * k - 1 - oldBaseRow
    }
    for (let c = 0; c < w; c++) {
      const g = board.cells[oldBaseRow * w + c]
      if (flapRow >= 0 && flapRow <= h - 1) {
        const f = board.cells[flapRow * w + c]
        const { val, kind } = resolveOverlap(f, g)
        cells[ns * w + c] = val
        if (kind === 'seal') seals++
        else if (kind === 'jam') jamsFormed++
        overlaps.push({
          flapIndex: flapRow * w + c,
          baseIndex: oldBaseRow * w + c,
          kind,
          color: kind === 'seal' || kind === 'transfer' ? f : val,
        })
      } else {
        cells[ns * w + c] = g
      }
    }
  }
  return {
    legal: true,
    axis,
    index,
    prefer,
    flapSide,
    overlaps,
    seals,
    jamsFormed,
    scoreDelta: scoreForSeals(seals),
    next: { w, h: newH, cells },
  }
}

/**
 * Applies a move to game state. rng-free. Never mutates input.
 * Illegal / already-finished moves are no-ops (state returned unchanged).
 */
export function fold(state: GameState, move: FoldMove): { state: GameState; preview: FoldPreview } {
  const preview = previewFold(state.board, move.axis, move.index, move.prefer)
  if (state.won || state.lost || !preview.legal) {
    return { state, preview }
  }

  const history = state.history.concat({
    board: state.board,
    score: state.score,
    foldsUsed: state.foldsUsed,
  })
  while (history.length > state.foldBudget) history.shift()

  const board = preview.next
  const foldsUsed = state.foldsUsed + 1
  let score = state.score + preview.scoreDelta
  let won = false
  let lost = false

  if (isWon(board)) {
    won = true
    if (foldsUsed <= state.par) score += PAR_BONUS
  } else if (hasJam(board) || (board.w === 1 && board.h === 1) || foldsUsed >= state.foldBudget) {
    // A jam can never be cleared, so the board is unwinnable from here: end the run
    // immediately (an Unfold still rewinds it, since undo clears `lost`).
    lost = true
  }

  return {
    state: { ...state, board, score, foldsUsed, won, lost, history },
    preview,
  }
}

/**
 * Consumes one unfold: pops the newest Snapshot, restoring board/score/foldsUsed
 * exactly, decrements unfoldsLeft, clears won/lost. No-op if pool/history empty.
 */
export function undo(state: GameState): GameState {
  if (state.unfoldsLeft <= 0 || state.history.length === 0) return state
  const history = state.history.slice()
  const snap = history.pop() as Snapshot
  return {
    ...state,
    board: snap.board,
    score: snap.score,
    foldsUsed: snap.foldsUsed,
    unfoldsLeft: state.unfoldsLeft - 1,
    won: false,
    lost: false,
    history,
  }
}

// ---------------------------------------------------------------------------
// 1.6 Board generation (provably solvable, yields par) — rng-only entry point
// ---------------------------------------------------------------------------

/**
 * Generation = K inverse folds from a 1×1 empty paper. Each inverse fold GROWS
 * the paper on the low side and plants a matched pair such that the FORWARD fold
 * seals it and exactly reproduces the pre-growth grid. Replaying `solution`
 * forward therefore always wins in exactly par = K folds.
 */
export function generateBoard(
  rng: Rng,
  level: number,
): { board: Board; par: number; solution: FoldMove[] } {
  const K = Math.min(3 + (level - 1), 7)
  let board: Board = { w: 1, h: 1, cells: [EMPTY] }
  const gen: FoldMove[] = []
  let color = 0

  for (let step = 0; step < K; step++) {
    const aMaxV = Math.min(board.w, MAX_DIM - board.w)
    const aMaxH = Math.min(board.h, MAX_DIM - board.h)
    const canV = aMaxV >= 1
    const canH = aMaxH >= 1
    if (!canV && !canH) break

    // Pick an axis, biasing toward growing the smaller current dim (squarer boards).
    let axis: Axis
    if (canV && canH) {
      if (board.w < board.h) axis = rng() < 0.8 ? 'v' : 'h'
      else if (board.h < board.w) axis = rng() < 0.8 ? 'h' : 'v'
      else axis = rng() < 0.5 ? 'v' : 'h'
    } else {
      axis = canV ? 'v' : 'h'
    }

    const aMax = axis === 'v' ? aMaxV : aMaxH
    const a = 1 + Math.floor(rng() * aMax) // flap width in [1, aMax]

    const grown = growLow(board, axis, a, color)
    board = grown.board
    if (grown.planted) color += 1
    gen.push({ axis, index: a, prefer: 'low' })
  }

  const solution = gen.slice().reverse() // FORWARD order: last-grown flap folds first
  return { board, par: gen.length, solution }
}

/**
 * Grow the paper by `a` on the LOW side of `axis`. Old content shifts to the HIGH
 * side (base). Plants at most one matched pair (color) into the first EMPTY overlap
 * slot so the inverse forward fold seals it. Returns the grown board + whether a
 * pair was planted.
 */
function growLow(
  board: Board,
  axis: Axis,
  a: number,
  color: number,
): { board: Board; planted: boolean } {
  const { w, h } = board
  let planted = false

  if (axis === 'v') {
    const newW = w + a
    const cells = new Array<Cell>(newW * h).fill(EMPTY)
    for (let r = 0; r < h; r++) {
      for (let j = 0; j < a; j++) {
        const oldPairedCol = a - 1 - j // old col in [0, a-1]
        const oldVal = board.cells[r * w + oldPairedCol]
        const baseNewCol = 2 * a - 1 - j // in [a, 2a-1]
        const flapNewCol = j // in [0, a-1]
        if (oldVal === EMPTY && !planted) {
          cells[r * newW + baseNewCol] = color
          cells[r * newW + flapNewCol] = color
          planted = true
        } else {
          cells[r * newW + flapNewCol] = EMPTY
          cells[r * newW + baseNewCol] = oldVal
        }
      }
      // Copy remaining non-overlap base cells verbatim: old cols [a, w-1] -> new [2a, w+a-1].
      for (let oldCol = a; oldCol < w; oldCol++) {
        cells[r * newW + oldCol + a] = board.cells[r * w + oldCol]
      }
    }
    return { board: { w: newW, h, cells }, planted }
  }

  // Horizontal growth: add `a` rows on top.
  const newH = h + a
  const cells = new Array<Cell>(w * newH).fill(EMPTY)
  for (let c = 0; c < w; c++) {
    for (let j = 0; j < a; j++) {
      const oldPairedRow = a - 1 - j
      const oldVal = board.cells[oldPairedRow * w + c]
      const baseNewRow = 2 * a - 1 - j
      const flapNewRow = j
      if (oldVal === EMPTY && !planted) {
        cells[baseNewRow * w + c] = color
        cells[flapNewRow * w + c] = color
        planted = true
      } else {
        cells[flapNewRow * w + c] = EMPTY
        cells[baseNewRow * w + c] = oldVal
      }
    }
    for (let oldRow = a; oldRow < h; oldRow++) {
      cells[(oldRow + a) * w + c] = board.cells[oldRow * w + c]
    }
  }
  return { board: { w, h: newH, cells }, planted }
}

// ---------------------------------------------------------------------------
// 1.7 Session helpers
// ---------------------------------------------------------------------------

export function newGame(rng: Rng, mode: Mode, seed: number, level: number): GameState {
  const { board, par, solution } = generateBoard(rng, level)
  return {
    board,
    par,
    foldsUsed: 0,
    foldBudget: par + FOLD_SLACK,
    unfoldsLeft: UNFOLD_POOL,
    score: 0,
    seed,
    mode,
    level,
    solution,
    history: [],
    won: false,
    lost: false,
  }
}

export function nextLevel(state: GameState, rng: Rng, seed: number): GameState {
  const level = state.level + 1
  const { board, par, solution } = generateBoard(rng, level)
  return {
    ...state,
    board,
    par,
    foldsUsed: 0,
    foldBudget: par + FOLD_SLACK,
    unfoldsLeft: UNFOLD_POOL,
    seed,
    level,
    solution,
    history: [],
    won: false,
    lost: false,
  }
}

/** Pure hash of a "YYYY-MM-DD" string -> 32-bit seed. Date is passed IN, never read here. */
export function dailySeed(dateISO: string): number {
  let h = 2166136261 >>> 0 // FNV-1a offset basis
  for (let i = 0; i < dateISO.length; i++) {
    h ^= dateISO.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}
